fields.InputDefinition:
{
  "goal": "Open a record: open the 'Events' (or 'Members') entity via the LEFT sidebar 'Search entities...' box, click a row, then click 'Open Full Record'. The record opens as a TAB in the top workspace bar alongside the 'Home' tab. Click the 'Home' tab to switch back to Home, then click the record's tab to switch back to the record. Verify switching between the Home tab and the record tab works and each shows its own content. (You do NOT need multiple record tabs — this verifies tab navigation between Home and an open record.) Pages can take 10-30s to load — wait, don't navigate away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 40,
  "judgeValidationCriteria": [
    "A record opened as a workspace tab alongside the Home tab",
    "Switching between the Home tab and the record tab works, each showing its own content",
    "No error messages, blank screens, or crash pages"
  ]
}
